#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    // Expect exactly two arguments: shift and input string
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    // Validate that the shift argument is a proper integer string (optional sign, then digits only)
    const char *p = argv[1];
    if (*p == '+' || *p == '-')
        p++;
    if (!isdigit((unsigned char)*p)) {
        puts("USAGE");
        return 0;
    }
    while (isdigit((unsigned char)*p))
        p++;
    if (*p != '\0') {
        puts("USAGE");
        return 0;
    }

    // Convert shift to integer and reduce modulo 26 (handle negative values)
    long shift = strtol(argv[1], NULL, 10);
    shift %= 26;
    if (shift < 0)
        shift += 26;

    const char *input = argv[2];
    size_t len = strlen(input);
    if (len > 0x400) { // limit as observed in the binary
        puts("USAGE");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (c >= 'A' && c <= 'Z') {
            c = (c - 'A' + (unsigned)shift) % 26 + 'A';
        } else if (c >= 'a' && c <= 'z') {
            c = (c - 'a' + (unsigned)shift) % 26 + 'a';
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
